import {visitIntent,visitProducts,shopOffers} from './visit-intent.js';
import {visitStatus,kmBetween} from './visit-hours.js';
import {formatDate} from './dates.js';
export function initVisitPlanner({state,shops,hydrate,$,esc,fa,locationModal,openProduct}){
 const host=document.createElement('section');host.id='visitPlanner';host.hidden=true;document.querySelector('.home-search').after(host);
 let offers=[],excluded=new Set(),map,markers=new Map(),selected=null,seq=0,visibleCount=4,resizeObserver;
 const clock=()=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());
 function arrival(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return new Date(`${parts.year}-${parts.month}-${parts.day}T${$('#arrivalClock').value||clock()}:00+03:30`)}
 function shell(query){resizeObserver?.disconnect();map?.remove();map=null;markers.clear();selected=null;document.body.classList.remove('home');host.hidden=false;document.body.classList.add('visit-mode');host.innerHTML=`<div class="visit-heading"><div><p class="small">خرید حضوری · تصمیم پیش از حرکت</p><h1>برای ${esc(query)} کجا بروم؟</h1></div><button id="visitBack">جستجوی تازه</button></div><div class="visit-controls"><button id="visitOrigin">⌖ ${esc(state.point.label)} · تغییر مبدأ</button><label>ساعت رسیدن امروز <input id="arrivalClock" type="time" value="${clock()}" required></label><label>فرصت خرید <select id="shoppingMargin"><option value="15">۱۵ دقیقه</option><option value="30">۳۰ دقیقه</option><option value="45">۴۵ دقیقه</option></select></label><button id="visitRefresh">بررسی دوباره</button></div><p class="small">ساعت رسیدن را خودت تعیین کن؛ فاصله‌های زیر مستقیم‌اند و زمان سفر نیستند. برنامهٔ کاری، قیمت و موجودی تأیید زنده ندارند.</p><p id="visitSummary" role="status" aria-live="polite">در حال بررسی فروشگاه‌ها…</p><div class="visit-layout"><div id="visitMap" aria-label="نقشهٔ تعاملی فروشگاه‌ها"></div><div id="visitCards"></div></div><div id="visitAlternative"></div>`;
 $('#visitBack').onclick=()=>{host.hidden=true;document.body.classList.remove('visit-mode');document.body.classList.add('home');window.scrollTo(0,0)};$('#visitOrigin').onclick=locationModal;$('#visitRefresh').onclick=render;$('#arrivalClock').onchange=render;$('#shoppingMargin').onchange=render;
 }
 function pick(id,fromMap=false){selected=id;host.querySelectorAll('[data-visit-card]').forEach(e=>e.classList.toggle('selected',e.dataset.visitCard===id));const marker=markers.get(id);if(marker){map.invalidateSize({pan:false});map.setView(marker.getLatLng(),16,{animate:false});marker.openTooltip()}if(fromMap)host.querySelector(`[data-visit-card="${CSS.escape(id)}"]`)?.scrollIntoView({block:"nearest",behavior:"smooth"});else if(matchMedia("(max-width:700px)").matches)$("#visitMap").scrollIntoView({block:"center",behavior:"smooth"})}
 function render(){if(!$('#arrivalClock').checkValidity())return;const date=arrival(),margin=+$('#shoppingMargin').value;$('#visitOrigin').textContent='⌖ '+state.point.label+' · تغییر مبدأ';const list=offers.filter(o=>!excluded.has(o.id)).map(o=>({...o,d:kmBetween(state.point,o.s),h:visitStatus(o.s,date,margin)}));const rank=o=>o.h.open===true?(o.h.enough?0:1):o.h.open===null?2:3;list.sort((a,b)=>rank(a)-rank(b)||(a.d??Infinity)-(b.d??Infinity));const near=list.filter(o=>o.d!==null&&o.d<=2),good=list.filter(o=>o.h.open&&o.h.enough);const shown=list.slice(0,visibleCount);
 $('#visitSummary').textContent=`${formatDate(date,true)} · `+(good.length?`${fa(good.length)} فروشگاه طبق برنامه فرصت خرید دارد؛ موجودی را استعلام کن.`:'باز بودن هیچ‌کدام از این فروشگاه‌ها تأیید نشده؛ قبل از حرکت استعلام کن.')+(list.length>visibleCount?` ${fa(visibleCount)} گزینهٔ اول از ${fa(list.length)} فروشگاه نمایش داده شده.`:'');
 $('#visitCards').innerHTML=shown.map((o,i)=>`<article data-visit-card="${esc(o.id)}" class="visit-card ${selected===o.id?'selected':''}"><button class="visit-card-title" data-pick="${esc(o.id)}">${fa(i+1)}. ${esc(o.s.name)}</button><p class="visit-product">${esc(o.p.title)}</p><strong>${o.price?fa(o.price)+' تومان':'قیمت نامشخص'}</strong><p class="small">${o.d===null?'مختصات نامشخص':fa(o.d.toFixed(1))+' کیلومتر فاصلهٔ مستقیم'} · ${esc(o.s.address||o.s.location_label||'آدرس نامشخص')}</p><span class="badge ${o.h.open&&o.h.enough?'green':'gray'}">${o.h.open===null?'ساعت کاری نامشخص':o.h.open?(o.h.enough?'طبق برنامه فرصت کافی داری':'ممکن است فرصت خرید کافی نباشد')+' · '+fa(o.h.remaining)+' دقیقه تا پایان شیفت':'در ساعت رسیدن، طبق برنامه بسته است'}</span><div class="shop-actions"><button data-route-shop="${esc(o.id)}">مسیر و نقشه</button><button data-visit-product="${esc(o.p.id)}">جزئیات کالا</button><button data-visit-fail="${esc(o.id)}">بسته بود؛ جایگزین</button></div></article>`).join('')||'<p>گزینه‌ای باقی نمانده؛ نام دقیق‌تر کالا یا مبدأ دیگری را امتحان کن.</p>';
 if(list.length>shown.length)$('#visitCards').insertAdjacentHTML('beforeend','<button data-visit-more>نمایش فروشگاه‌های بیشتر</button>');
 $('#visitAlternative').innerHTML=`<details><summary>اگر هیچ گزینه‌ای مناسب نبود چه کنم؟</summary><p>می‌توانی فروشگاه‌های ثبت‌نشدهٔ اطراف را روی نقشهٔ بیرونی جستجو کنی. حضور روی نقشه به معنی موجودی کالا یا باز بودن نیست؛ پیش از حرکت بررسی کن.</p><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/${encodeURIComponent($('#homeQuery').value+' نزدیک من')}/@${state.point.lat},${state.point.lon},15z">جستجوی فروشگاه‌های دیگر در نقشه ↗</a><p class="small">این پیوند مبدأ را به سرویس نقشه می‌فرستد. هنوز جستجوی بیرونی یا تأیید فروشگاه انجام نشده است.</p></details>`;
 if(window.L){if(!map){map=L.map('visitMap',{zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([state.point.lat,state.point.lon],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);resizeObserver=new ResizeObserver(()=>{if(map)map.invalidateSize({pan:false})});resizeObserver.observe($('#visitMap'))}markers.forEach(m=>m.remove());markers.clear();const origin=L.circleMarker([state.point.lat,state.point.lon],{color:'#334155',radius:9}).addTo(map).bindTooltip('مبدأ انتخابی');markers.set('_origin',origin);const bounds=[[state.point.lat,state.point.lon]];shown.forEach((o,i)=>{if(o.d===null)return;const m=L.marker([o.s.lat,o.s.lon],{icon:L.divIcon({className:'visit-pin',html:`<span>${fa(i+1)}</span>`,iconSize:[30,36],iconAnchor:[15,36]})}).addTo(map).bindTooltip(Object.assign(document.createElement('span'),{textContent:`${fa(i+1)}. ${o.s.name}`}));m.on('click',()=>pick(o.id,true));markers.set(o.id,m);bounds.push([o.s.lat,o.s.lon])});map.invalidateSize({pan:false});const active=shown.find(o=>o.id===selected&&o.d!==null)||shown.find(o=>o.d!==null);const frame=active?[[state.point.lat,state.point.lon],[active.s.lat,active.s.lon]]:bounds.slice(0,1);map.fitBounds(frame,{padding:[40,40],maxZoom:15,animate:false});requestAnimationFrame(()=>map?.invalidateSize({pan:false}))}
 }
 async function start(query){if(!query.trim())return;const intent=visitIntent(query);$('#homeQuery').value=query;const run=++seq;excluded.clear();visibleCount=4;offers=[];shell(query);window.scrollTo({top:0});try{const r=await fetch('/api/search?'+new URLSearchParams({q:intent.query,limit:48}),{signal:AbortSignal.timeout(60000)});if(!r.ok)throw Error();const data=await r.json();const products=[];for(let i=0;i<data.results.length;i+=6){products.push(...await Promise.all(data.results.slice(i,i+6).map(hydrate)));if(run!==seq)return}offers=shopOffers(visitProducts(products,intent),shops);render()}catch{if(run===seq)$('#visitSummary').textContent='دریافت گزینه‌ها ممکن نشد؛ دوباره جستجو کن.'}}
 host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-visit-more')){visibleCount+=4;render()}if(b.dataset.pick)pick(b.dataset.pick);if(b.dataset.visitFail){excluded.add(b.dataset.visitFail);render()}if(b.dataset.visitProduct){host.hidden=true;document.body.classList.remove('visit-mode');openProduct(b.dataset.visitProduct)}});
 $('#homeSearchForm').onsubmit=e=>{e.preventDefault();start($('#homeQuery').value.trim())};$('#homeGuide').onclick=()=>{start('شارژر گوشی');setTimeout(()=>{if($('#arrivalClock')){$('#arrivalClock').value='23:30';render()}},0)};
 document.querySelector('.brand').addEventListener('click',()=>{host.hidden=true;document.body.classList.remove('visit-mode')});
 return {start};
}
